static const char art3m1s_image_quad_cg[] = "// art3m1s explicit-UV image shader. Same vertex interface and scissor behavior\n// as NanoVG's image fill; straight RGBA becomes premultiplied before blending.\nuniform float4 frag[11];\n#define scissorMat float3x3(frag[0].xyz, frag[1].xyz, frag[2].xyz)\n#define innerCol frag[6]\n#define scissorExt frag[8].xy\n#define scissorScale frag[8].zw\n\nfloat4 main(\n    uniform sampler2D image : TEXUNIT0,\n    float2 ftcoord : TEXCOORD0,\n    float2 fpos : TEXCOORD1\n) : COLOR {\n    float4 color = tex2D(image, ftcoord);\n    color.rgb *= color.a;\n    float2 sc = abs(mul(scissorMat, float3(fpos, 1.0)).xy) - scissorExt;\n    sc = saturate(float2(0.5, 0.5) - sc * scissorScale);\n    return color * innerCol * sc.x * sc.y;\n}\n";